/// Error Code
///
/// strata_protocol::api::ErrorCode; each has one HTTP status.
///
/// Specification type `error-code`: an enumeration, serialised as the specification's values.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub enum ErrorCode {
    /// The value `unauthenticated`.
    #[serde(rename = "unauthenticated")]
    Unauthenticated,
    /// The value `forbidden`.
    #[serde(rename = "forbidden")]
    Forbidden,
    /// The value `not-found`.
    #[serde(rename = "not-found")]
    NotFound,
    /// The value `conflict`.
    #[serde(rename = "conflict")]
    Conflict,
    /// The value `invalid`.
    #[serde(rename = "invalid")]
    Invalid,
    /// The value `throttled`.
    #[serde(rename = "throttled")]
    Throttled,
    /// The value `unavailable`.
    #[serde(rename = "unavailable")]
    Unavailable,
    /// The value `internal`.
    #[serde(rename = "internal")]
    Internal,
}

impl ErrorCode {
    /// The value as the specification writes it.
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::Unauthenticated => "unauthenticated",
            Self::Forbidden => "forbidden",
            Self::NotFound => "not-found",
            Self::Conflict => "conflict",
            Self::Invalid => "invalid",
            Self::Throttled => "throttled",
            Self::Unavailable => "unavailable",
            Self::Internal => "internal",
        }
    }
}

